use super::*;
#[test] fn sequences_hand_checks(){let mut p=Params::defaults(&params());let d=data(&p).unwrap();assert_eq!(d.a.iter().map(|x|x.v).collect::<Vec<_>>(),vec![2.,3.,4.,5.,6.,7.,8.,9.]);assert_eq!(d.s[7].q,Some((44,1)));p.set_s("mode","Geometric");p.set_s("ratio","-1/2");let d=data(&p).unwrap();assert_eq!(d.a[3].q,Some((-1,4)));assert_eq!(d.s[3].q,Some((5,4)));assert_eq!(limits(&p,&d).1.unwrap().q,Some((4,3)));p.set_s("mode","Recursive");p.set_s("first","1");assert_eq!(data(&p).unwrap().a[7].v,21.);p.set_s("mode","Explicit");assert_eq!(data(&p).unwrap().a[5].q,Some((1,6)));assert_eq!(limits(&p,&data(&p).unwrap()).0.unwrap().v,0.);}
#[test]fn sequences_sweep(){for mode in ["Arithmetic","Geometric","Explicit","Recursive"]{for size in ["Small","Medium","Large"]{for count in [3,8,24]{for layout in ["One grid","Two aligned graphs","Number line"]{let mut p=Params::defaults(&params());p.set_s("mode",mode);p.set_s("label_size",size);p.set_i("count",count);p.set_s("layout",layout);let a=render(&p);assert_eq!(a,render(&p));assert!(!a.contains("NaN"));assert!(a.len()<150000);assert!(super::super::to_png(&a,0.2).is_ok());}}}}}
